function standardOutcomeHtml(project: Project): string {
  const typeLabel = project.type === "legacy-modernization" ? "Modern proposal" : "Advantage 360 proposal";
  const priorityCount = project.findings.filter((item) => item.severity === "priority").length;
  const attentionCount = project.findings.filter((item) => item.severity === "attention").length;
  const healthyCount = project.findings.filter((item) => item.severity === "healthy").length;
  const findings = project.findings.map((item) => `<article class="finding ${item.severity}"><div><span>${escapeHtml(categoryLabel(item.category))}</span><em>${escapeHtml(item.severity)}</em></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.clientSummary)}</p></article>`).join("");
  const investment = project.pricing.monthly || project.pricing.oneTime ? `<section><span class="kicker">Investment</span><div class="investment"><article><small>Monthly</small><strong>$${project.pricing.monthly.toLocaleString("en-US", { minimumFractionDigits: 2 })}</strong></article><article><small>One-time</small><strong>$${project.pricing.oneTime.toLocaleString("en-US", { minimumFractionDigits: 2 })}</strong></article></div></section>` : "";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(clientFacingDocumentTitle(project))}</title><style>:root{--navy:#071a34;--blue:#1766de;--ink:#0b1830;--muted:#66758a;--line:#dfe6ef;--bg:#eef2f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{width:min(1180px,calc(100% - 36px));margin:auto;padding:28px 0 80px}.top,.footer{display:flex;justify-content:space-between;align-items:center;color:#748197;font-size:12px;padding:18px 0}.brand-inline{display:inline-flex;align-items:center}.brand-inline img{width:166px;height:auto;object-fit:contain;display:block}.hero{border-radius:32px;padding:58px;background:linear-gradient(130deg,#06172f,#0b336c 60%,#1766de);color:white}.hero h1{font-size:clamp(42px,7vw,82px);line-height:.98;margin:0 0 20px}.hero p{line-height:1.65;color:#dceaffc9}.kicker{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:850}.score-grid,.investment{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0 48px}.score-grid article,.investment article,.finding,.recommendation{background:white;border:1px solid var(--line);border-radius:20px;padding:24px}.score-grid strong,.investment strong{display:block;font-size:36px}.finding-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.finding{border-top:5px solid #7098dc}.finding.priority{border-top-color:#ef8062}.finding.attention{border-top-color:#d9aa48}.finding.healthy{border-top-color:#35aa91}.finding>div{display:flex;justify-content:space-between}.finding span,.finding em{font-style:normal;font-size:10px;text-transform:uppercase;color:#7c899b}.finding p,.recommendation p{color:var(--muted);line-height:1.65}.recommendation-list{display:grid;gap:12px}.recommendation{display:grid;grid-template-columns:55px 1fr;gap:18px}.toolbar{position:fixed;right:20px;bottom:20px}.toolbar button{border:0;border-radius:14px;padding:13px 17px;background:var(--navy);color:white;font-weight:800}@media(max-width:760px){.score-grid,.investment,.finding-grid{grid-template-columns:1fr}}@media print{@page{size:landscape;margin:.34in}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.toolbar{display:none}main{width:100%;padding:0}.hero{break-after:page;box-shadow:none}main>section:not(.hero){break-before:page}article,.finding,.recommendation{break-inside:avoid}}${PDF_HANDOFF_CSS}</style></head><body><main><header class="top"><span class="brand-inline"><img src="${ADVANTAGE_LOGO_DATA_URI}" alt="Advantage Technologies"></span><span>${escapeHtml(typeLabel)}</span></header><section class="hero"><span class="kicker">Prepared for ${escapeHtml(project.client.name)}</span><h1>${escapeHtml(project.presentation.title)}</h1><p>${escapeHtml(project.presentation.executiveSummary)}</p></section><div class="score-grid"><article><strong>${priorityCount}</strong><small>Priority items</small></article><article><strong>${attentionCount}</strong><small>Needs attention</small></article><article><strong>${healthyCount}</strong><small>Healthy findings</small></article></div>${painPoints(project)}<section><span class="kicker">The review</span><h2>What we found</h2><div class="finding-grid">${findings}</div></section>${hipaaSummaryHtml(project)}<section><span class="kicker">Planning</span><h2>Recommended next steps</h2><div class="recommendation-list">${recommendationsHtml(project)}</div></section>${investment}<section><span class="kicker">Final recap</span><h2>Review complete</h2><p>${escapeHtml(project.hipaa.enabled ? "The findings, readiness discussion, proposed solution, and next actions are captured in this package." : "The findings, proposed solution, and next actions are captured in this package.")}</p></section><footer class="footer"><span class="brand-inline"><img src="${ADVANTAGE_LOGO_DATA_URI}" alt="Advantage Technologies"></span><span>Generated locally from approved workspace information</span></footer><div class="toolbar"><button onclick="window.print()">Print or save PDF</button></div></main></body></html>`;
}

type OutcomeHtmlOptions = { autoPrint?: boolean };

function autoPrintScript(): string {
  return `<script>(()=>{const printWhenReady=()=>window.setTimeout(()=>{window.focus();window.print()},350);if(document.readyState==="complete"){printWhenReady()}else{window.addEventListener("load",printWhenReady,{once:true})}})();</script>`;
}

export function outcomeHtml(project: Project, options: OutcomeHtmlOptions = {}): string {
  const html = project.type === "client-report" && clientReportAvailable(project)
    ? clientReportHtml(project)
    : project.type !== "client-report"
      ? prospectProposalHtml(project)
      : standardOutcomeHtml(project);
  return options.autoPrint ? html.replace("</body>", `${autoPrintScript()}</body>`) : html;
}


function openPrintFallback(project: Project): void {
  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    window.alert("The fillable PDF could not be created and the browser blocked the print fallback. Please allow pop-ups, then try again.");
    return;
  }
  printWindow.document.open();
  printWindow.document.write(outcomeHtml(project, { autoPrint: true }));
  printWindow.document.close();
  printWindow.focus();
}

export async function downloadOutcomePdf(project: Project): Promise<void> {
  if (project.type === "client-report") {
    const reconciliation = inventoryReconciliation(project);
    if (!reconciliation.passed) {
      window.alert("The authoritative Ninja / Client Compass inventory does not reconcile with the report output. Download inventory diagnostics and refresh source data before sharing.");
      return;
    }
  }
  try {
    await downloadFillableClientPdf(outcomeHtml(project), clientFacingDocumentTitle(project));
  } catch (error) {
    console.error("Fillable client PDF generation failed; opening browser print fallback.", error);
    window.alert("The fillable PDF could not be created in this browser. A print-ready version will open instead; choose Save as PDF.");
    openPrintFallback(project);
  }
}
